#define _CRT_SECURE_NO_WARNINGS

#include <algorithm>
#include <cstdio>
#include <iostream>

using namespace std;

typedef long long ll;

int a[100000];
int b[100000];
int n, d, x;

int getNextX() {
    x = ((ll)x * 37 + 10007) % 1000000007;
    return x;
}

void initAB() {
    for (int i = 0; i < n; ++i) {
        a[i] = i + 1;
    }

    for (int i = 0; i < n; ++i) {
        int j = getNextX() % (i + 1);
        swap(a[i], a[j]);
    }

    for (int i = 0; i < n; ++i) {
        b[i] = (i < d ? 1 : 0);
    }

    for (int i = 0; i < n; ++i) {
        swap(b[i], b[getNextX() % (i + 1)]);
    }
}

int s = 30;
int inva[100008];
int bidx[100008];

int main() {
    cin >> n >> d >> x;
    initAB();

    for (int i = 0; i < n; ++i) {
        inva[a[i]] = i;
    }

    int count = 0;
    for (int i = 0; i < n; ++i) {
        if (b[i]) {
            bidx[count++] = i;
        }
    }
    bidx[count] = 987654321;

    for (int i = 0; i < n; ++i) {
        bool found = false;

        for (int val = n; val >= max(1, n - s); --val) {
            int j = inva[val];
            if (j <= i && b[i - j]) {
                cout << val << '\n';
                found = true;
                break;
            }
        }

        if (found) {
            continue;
        }

        int ans = 0;
        for (int j = 0; bidx[j] <= i; ++j) {
            ans = max(ans, a[i - bidx[j]]);
        }
        cout << ans << '\n';
    }

    return 0;
}

